CREATE TABLE "merk" (
	"id" bigint PRIMARY KEY GENERATED BY DEFAULT AS IDENTITY (sequence name "merk_id_seq" INCREMENT BY 1 MINVALUE 1 MAXVALUE 9223372036854775807 START WITH 1 CACHE 1),
	"nama" varchar(50) NOT NULL,
	"keterangan" varchar(150),
	"status_aktif" varchar(10) DEFAULT 'AKTIF' NOT NULL,
	"dibuat_pada" timestamp with time zone DEFAULT now() NOT NULL,
	"diubah_pada" timestamp with time zone,
	CONSTRAINT "merk_nama_key" UNIQUE("nama"),
	CONSTRAINT "chk_merk_status" CHECK (status_aktif in ('AKTIF','NONAKTIF'))
);
--> statement-breakpoint
ALTER TABLE "barang" ADD COLUMN "id_merk" bigint;--> statement-breakpoint
ALTER TABLE "barang" ADD CONSTRAINT "barang_id_merk_fkey" FOREIGN KEY ("id_merk") REFERENCES "public"."merk"("id") ON DELETE no action ON UPDATE no action;--> statement-breakpoint
CREATE INDEX "idx_barang_merk" ON "barang" USING btree ("id_merk");--> statement-breakpoint
-- Pindahkan merk teks lama ke tabel merk (nama sama tanpa membedakan huruf besar/kecil = satu merk).
INSERT INTO "merk" ("nama")
SELECT DISTINCT ON (lower(trim("merk"))) trim("merk")
FROM "barang"
WHERE "merk" IS NOT NULL AND trim("merk") <> ''
ORDER BY lower(trim("merk")), trim("merk") COLLATE "C";--> statement-breakpoint
UPDATE "barang" AS b SET "id_merk" = m."id"
FROM "merk" AS m
WHERE b."merk" IS NOT NULL AND lower(trim(b."merk")) = lower(m."nama");
